	sf(refresh, "session", "", "", "Refresh only this session (id or unique prefix)")
	bf(refresh, "json", "", "Machine-readable output")
	recover := c.newCmd(sessions, "recover", "Rebuild canonical session data into a separate clean database",
		"Offline, non-destructive recovery for a damaged state.db. The source database and its WAL/SHM/rollback-journal sidecars are copied before SQLite opens anything. Canonical rows are rebuilt into a new output database; derived search indexes are recreated and the active database is never replaced automatically.")
